import { createHash } from "node:crypto";
import { mkdir, readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";

const repositoryRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outputPath = path.join(repositoryRoot, "src/generated/productionPolicyBundle.mjs");

const policyDocuments = {
  privacy: "src/app/privacy/page.tsx",
  terms: "src/app/terms/page.tsx",
  consumerHealthData: "src/app/consumer-health-data/page.tsx",
  subprocessors: "src/app/subprocessors/page.tsx",
  dataRetentionRunbook: "DATA_RETENTION_DELETION_RUNBOOK.md",
  incidentResponseRunbook: "INCIDENT_RESPONSE_RUNBOOK.md",
  monitoringRunbook: "MONITORING_ALERTING_RUNBOOK.md",
  legalReviewPacket: "LEGAL_REVIEW_PACKET.md",
  privacyRightsOperations: "PRIVACY_RIGHTS_OPERATIONS.md",
  billingOperationsRunbook: "BILLING_OPERATIONS_RUNBOOK.md",
  billingLaunchChecklist: "BILLING_LAUNCH_CHECKLIST.md",
};

function sha256(value) {
  return `sha256:${createHash("sha256").update(value).digest("hex")}`;
}

const documentDigests = {};
for (const [id, relativePath] of Object.entries(policyDocuments)) {
  const body = await readFile(path.join(repositoryRoot, relativePath));
  documentDigests[id] = sha256(body);
}

const bundleDigest = sha256(
  JSON.stringify(
    Object.fromEntries(
      Object.entries(documentDigests).sort(([left], [right]) => left.localeCompare(right))
    )
  )
);

const generated = `// Generated by scripts/generate-production-policy-bundle.mjs. Do not edit manually.\n\nexport const productionPolicyDocumentPaths = ${JSON.stringify(policyDocuments, null, 2)};\n\nexport const productionPolicyDocumentDigests = ${JSON.stringify(documentDigests, null, 2)};\n\nexport const productionPolicyBundleSha256 = ${JSON.stringify(bundleDigest)};\n`;

await mkdir(path.dirname(outputPath), { recursive: true });
await writeFile(outputPath, generated, "utf8");
console.log(`Production policy bundle generated: ${bundleDigest}`);
